<template>
  <div class="setMonsType">
    <title-line :title="title" />
    <div class="card-container">
      <div :class="chiptype=='1'?'select-card':'unselect-card'" @click="chiptype='1'">
        <div class="icon-usdt" />
        <div class="label">{{ $t('szcmlx.szcmlx02') }}</div>
      </div>
      <div :class="chiptype=='2'?'select-card':'unselect-card'" @click="chiptype='2'">
        <div class="icon-cny" />
        <div class="label">{{ $t('szcmlx.szcmlx03') }}</div>
      </div>
    </div>
    <div class="select-container">
      <svg-icon class="mine_icon" :icon-class="iconNameLeft" :width="16" :height="16" @click="iconNameLeft='复选框_s'+themeColor;iconNameRight='复选框_n'" />
      <div class="select-text">{{ $t('szcmlx.szcmlx04') }}</div>
      <svg-icon class="mine_icon" :icon-class="iconNameRight" :width="16" :height="16" @click="iconNameRight='复选框_s'+themeColor;iconNameLeft='复选框_n'" />
      <div class="select-text">{{ $t('szcmlx.szcmlx05') }}</div>
    </div>
    <div class="submit-btn" @click="setchipalert()">{{ $t('szcmlx.szcmlx07') }}</div>
    <div class="tip-container">
      <div class="warning-icon" />
      <div class="tip-text">{{ $t('szcmlx.szcmlx08') }}</div>
    </div>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { getUserChiprate, setchipalert } from '@/api/user'

export default {
  components: {
    TitleLine
  },
  data() {
    return {
      themeColor: process.env.VUE_APP_BASE_THEME,
      title: this.$t('szcmlx.szcmlx01'),
      iconNameLeft: '复选框_s'+process.env.VUE_APP_BASE_THEME,
      iconNameRight: '复选框_n',
      currentValue: 'usdt',
      chiptype: '1'
    }
  },
  created() {
    this.updateData()
  },
  methods: {
    async updateData() {
      const res = await getUserChiprate()
      this.chiptype = res.chiptype
    },
    async setchipalert() {
      await setchipalert({ chiptype: this.chiptype, savedays: this.iconNameLeft === '复选框_s'+process.env.VUE_APP_BASE_THEME ? '1' : this.iconNameRight === '复选框_s'+process.env.VUE_APP_BASE_THEME ? '7' : '0' })
      this.$toast.success('提交成功')
      this.$router.go(-1)
    }
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
  }

}
</script>
